const PREFIX={'fa-light':'fal','fa-solid':'fas','fa-brands':'fab'};
function draw(root){
  root.querySelectorAll('i[class*="fa-"]').forEach(el=>{
    const cls=[...el.classList], style=cls.find(c=>PREFIX[c]), name=cls.find(c=>c.startsWith('fa-')&&!PREFIX[c]);
    const g=style&&name&&I[PREFIX[style]+':'+name.slice(3)]; if(!g) return;
    const [w,h]=g[0].split(' ').slice(2).map(Number);
    const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
    svg.setAttribute('viewBox',g[0]); svg.setAttribute('aria-hidden',el.getAttribute('aria-hidden')||'true'); svg.setAttribute('focusable','false');
    svg.setAttribute('class',[...cls,'fa-svg'].join(' '));
    svg.style.cssText='display:inline-block;height:1em;width:'+(w/h).toFixed(4)+'em;vertical-align:-0.125em;overflow:visible;fill:currentColor;';
    const p=document.createElementNS('http://www.w3.org/2000/svg','path'); p.setAttribute('d',g[1]); svg.appendChild(p);
    el.replaceWith(svg);
  });
}
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',()=>draw(document)); else draw(document);
